import{_ as l,f as s,c as a,d as e,l as i,t as c,F as d,h as p,u as m}from"./entry.0d887d5b.js";import{u}from"./useAssetUrl.21d89996.js";const g={__name:"ReadMore",props:{serviceThemeColor:{type:String,default:"#FFE33E"}},setup(o){const t=o;return(n,r)=>(s(),a("div",{class:"view-more-btn heding-color heading-font font-18 font-700 wow move-up",style:i({"--service-theme-color":t.serviceThemeColor})},r[0]||(r[0]=[e("span",null,"Read more",-1),e("span",{class:"btn-arrow"},null,-1)]),4))}},w=l(g,[["__scopeId","data-v-823a0197"]]);const v={class:"bg_color--14 text_area"},b={class:"call-content text-sm-start"},h={class:"heading heading-h2 wow move-up"},f={class:"heading heading-h4 wow move-up"},I={__name:"IdeoIntro",props:{data:{type:Object,default:()=>({bgImage:"",title:"",subTitle:"",content:[]})}},setup(o){const t=o;return(n,r)=>(s(),a("div",null,[e("div",{class:"brook-call-to-action bg_image--9",style:i({backgroundImage:`url(${("useAssetUrl"in n?n.useAssetUrl:m(u))(t.data.bgImage)})`})},[e("div",v,[e("div",b,[e("h2",h,c(t.data.title),1),e("h4",f,c(t.data.subTitle),1),(s(!0),a(d,null,p(t.data.content,_=>(s(),a("p",null,c(_),1))),256))])])],4)]))}},T=l(I,[["__scopeId","data-v-d1525585"]]),j={bgImage:"img/creativeLab/pexels-steve-1704119.jpg",title:"共學、共煮、共育──打造共享與成長的日常場域",subTitle:"從程式訓練到親子共育與永續課程，我們在生活中實踐支持與連結的工作方式",content:["好想數位共創雖以數位技術為人所知，但在技術實踐之外，我們也持續經營一系列更貼近人與生活的工作項目。長期運作的 Coding Training Camp，提供學員無償參與半年期的自學與交流計畫，透過陪伴與實作，讓初學者穩定成長為專業程式開發者，並進一步回過頭來帶領新學員，形成持續流動的學習循環。","除此之外，我們也經營共享廚房與親子共育空間。午餐共煮活動已舉辦多次，讓彼此在輕鬆煮食中建立連結，也有機會交換各自工作上的經驗與難題。未來也規劃邀請專業主廚帶領創意料理工作坊，讓生活與創造力一起發酵。親子空間的經營則回應我們對「育兒與工作不需二選一」的信念，我們相信，在支持彼此的社群裡，每個人都能被照顧，也能有所貢獻。","未來我們也將逐步推動與永續發展目標（SDGs & UN 2.0）對應的主題課程，將更多公共性議題與實踐的行動連結起來，讓「一起工作、一起生活」的理想，具體成為日常。"]},k={bgImage:"img/projects/pexels-markusspiske-1089440.jpg",title:"技術實踐 × 公私協力：打造多元產業的數位解方",subTitle:"從在地企業到公共治理，我們以模組化系統開發，推動產業升級與數位轉型，讓技術真正回應使用者的需求",content:["好想數位共創是一個致力於技術創新與社會實踐的工作室，長期參與企業與政府的數位轉型專案，涵蓋傳統產業、文教機構與公私協力計畫。在產業端，我們曾協助多家在地企業打造專屬內部管理系統，如全強營造、晉基營造與倫永計程車行，協助他們優化營運流程；同時，我們也開發如小南天旅住訂房系統、神不在場密室逃脫平台與福華飯店 POS 等 B2C 系統，提升客戶體驗與營運效率。","在與政府合作方面，我們參與了口罩地圖、台南打疫苗、台南宅照護與愛篩檢等公共衛生平台的設計與建置，透過簡潔易用的界面與精準的資料整合，有效回應疫情期間市民的實際需求。此外，我們也協助台南市政府開發廟宇導覽網站與市政儀表板，並與教育部、國立歷史博物館等單位合作推動文化與教育數位轉型。","我們擅長以模組化思維處理不同產業需求，提供彈性、穩定且具有延展性的系統開發服務，期待未來持續透過技術推動更多正向的改變。"]},C={bgImage:"img/nomads/pexels-462556744-31598876.jpg",title:"台南，一座值得停留的城市",subTitle:"從歷史文化體驗到在地生活連結，打造數位遊牧者友善的社群基地",content:["我們從今年開始投入數位遊牧社群的經營，期望打造一個讓外國旅人與在地緊密連結的生活場域。透過一系列與台南歷史文化相關的活動，我們邀請在地職人說故事、帶領散步、動手體驗，讓初來乍到的數位遊牧者不只是旅人，而能慢慢成為這座城市的一份子。","我們也積極串聯在地商家，共同思考數位遊牧者在台南生活的各種需求，從住宿、交通、飲食到工作場域，預計推出友善且合理的套裝方案，降低停留門檻，提升在地停留品質。我們相信，城市的溫度來自人與人的連結，而我們正在一點一滴，為這樣的連結打下基礎。"]};export{T as _,w as a,j as c,C as n,k as p};
